node -e '
const { resolveSession } = require("./src/session.js");

let calls = 0;
function makeIo(tenantId) {
  return {
    tenantId,
    async loadSession(id) { calls++; return { tenant: tenantId || "none", id }; }
  };
}

(async () => {
  // 1. Caching: same (tenant, session) pair loads storage only once.
  const ioA = makeIo("tenantA");
  const s1 = await resolveSession(ioA, "tenantA", "sess-1");
  const s2 = await resolveSession(ioA, "tenantA", "sess-1");
  console.log("cached same session:", s1 === s2, "| loadSession calls so far:", calls);

  // 2. No cross-tenant leak: same session id under different tenants.
  const ioB = makeIo("tenantB");
  const sB = await resolveSession(ioB, "tenantB", "sess-1");
  console.log("cross-tenant isolated:", sB.id === "sess-1" && sB.tenant === "tenantB" && sB !== s1, "| calls:", calls);

  // 3. Legacy 2-arg form with io.tenantId: cached + per-tenant.
  const before = calls;
  const l1 = await resolveSession(ioA, "sess-1");
  const l2 = await resolveSession(ioA, "sess-1");
  console.log("legacy 2-arg cached:", l1 === l2, "| extra calls:", calls - before);

  // 4. Legacy 2-arg without any tenant context: safe fallback (uncached).
  const ioN = { async loadSession(id) { calls++; return { id }; } };
  const before2 = calls;
  const n1 = await resolveSession(ioN, "sess-1");
  const n2 = await resolveSession(ioN, "sess-1");
  console.log("no-tenant falls back to load (uncached):", n1 !== n2 || calls - before2 === 2, "| extra calls:", calls - before2);
})();
'

